dataTableFormat:
{
  "is multi section": "true",
  "search parameters": [
    {
      "type": "string to array",
      "parameter": "userInput",
      "label": "Search e.g., polycystic ovary syndrome, red blood cell abnormality, muscle weakness, abnormal glucose uptake"
    }
  ],
  "shared resource": {
    "phenotype map": "cfde phenotypes"
  },
  "sections": [
    {
      "section id": "phenotypes_geneSet",
      "header": "CFDE phenotype x gene set associations",
      "data point": {
        "type": "api",
        "url": "https://search.hugeamp.org/api/search/pgvector/terms?q=$userInput&table-name=terms_cfde_all_mpnet_base_v2&top_k=1000",
        "parameters": [
          "userInput"
        ],
        "parameters type": "replace",
        "data type": "json",
        "data wrapper": [
          "results"
        ]
      },
      "table format": {
        "data convert": [
          {
            "type": "raw",
            "field name": "Association",
            "raw field": "term"
          },
          {
            "type": "raw",
            "field name": "Beta (uncorrected)",
            "raw field": "beta_uncorrected"
          },
          {
            "type": "raw",
            "field name": "phenotype id",
            "raw field": "phenotype"
          },
          {
            "type": "raw",
            "field name": "Gene set",
            "raw field": "gene_set"
          },
          {
            "type": "map name",
            "field name": "Phenotype",
            "raw field": "phenotype",
            "map": "shared resource",
            "map name": "phenotype map"
          },
          {
            "type": "raw",
            "field name": "Program",
            "raw field": "source"
          },
          {
            "type": "join multi",
            "field name": "Genes in gene set",
            "fields to join": [
              "phenotype id",
              "Gene set"
            ],
            "join by": [
              ","
            ]
          }
        ],
        "top rows": [
          "Association",
          "Phenotype",
          "Gene set",
          "Program",
          "Beta (uncorrected)",
          "Genes in gene set"
        ],
        "column formatting": {
          "Genes in gene set": {
            "type": [
              "dynamic subsection"
            ],
            "label": "Show",
            "subsection": {
              "data point": {
                "type": "bioindex",
                "url": "https://cfde-dev.hugeampkpnbi.org/api/bio/",
                "index": "pigean-joined-gene-set",
                "parameters": [
                  "phenotype",
                  "geneSet"
                ],
                "parameters type": "array",
                "data type": "bioindex"
              },
              "table format": {
                "pre filters": [
                  {
                    "field": "Source",
                    "type": "filter out",
                    "values": [
                      "gene_set_list_msigdb_nohp",
                      "gene_set_list_mouse_2024"
                    ]
                  },
                  {
                    "field": "Model",
                    "type": "filter out",
                    "values": [
                      "mouse"
                    ]
                  }
                ],
                "data convert": [
                  {
                    "type": "raw",
                    "field name": "Gene",
                    "raw field": "gene"
                  },
                  {
                    "type": "raw",
                    "field name": "Model",
                    "raw field": "gene_set_size"
                  },
                  {
                    "type": "raw",
                    "field name": "Overall score (GWAS support + gene set support)",
                    "raw field": "combined"
                  },
                  {
                    "type": "raw",
                    "field name": "GWAS support",
                    "raw field": "log_bf"
                  },
                  {
                    "type": "raw",
                    "field name": "Gene set support",
                    "raw field": "prior"
                  },
                  {
                    "type": "translate to categories",
                    "field name": "Evidence range (Overall score)",
                    "raw field": "combined",
                    "categories": [
                      {
                        "name": "Not Significant",
                        "condition": "less than",
                        "range": 1
                      },
                      {
                        "name": "Nominally Significant",
                        "condition": "and",
                        "range": [
                          1,
                          2
                        ]
                      },
                      {
                        "name": "Strongly Suggestive",
                        "condition": "and",
                        "range": [
                          2,
                          3
                        ]
                      },
                      {
                        "name": "Very Strong",
                        "condition": "greater than",
                        "range": 3
                      }
                    ]
                  },
                  {
                    "type": "translate to categories",
                    "field name": "Evidence range (GWAS support)",
                    "raw field": "log_bf",
                    "categories": [
                      {
                        "name": "Not Significant",
                        "condition": "less than",
                        "range": 1
                      },
                      {
                        "name": "Nominally Significant",
                        "condition": "and",
                        "range": [
                          1,
                          2
                        ]
                      },
                      {
                        "name": "Strongly Suggestive",
                        "condition": "and",
                        "range": [
                          2,
                          3
                        ]
                      },
                      {
                        "name": "Very Strong",
                        "condition": "greater than",
                        "range": 3
                      }
                    ]
                  },
                  {
                    "type": "translate to categories",
                    "field name": "Evidence range (Gene set support)",
                    "raw field": "prior",
                    "categories": [
                      {
                        "name": "Not Significant",
                        "condition": "less than",
                        "range": 1
                      },
                      {
                        "name": "Nominally Significant",
                        "condition": "and",
                        "range": [
                          1,
                          2
                        ]
                      },
                      {
                        "name": "Strongly Suggestive",
                        "condition": "and",
                        "range": [
                          2,
                          3
                        ]
                      },
                      {
                        "name": "Very Strong",
                        "condition": "greater than",
                        "range": 3
                      }
                    ]
                  },
                  {
                    "type": "raw",
                    "field name": "Source",
                    "raw field": "source"
                  }
                ],
                "top rows": [
                  "Gene",
                  "Overall score (GWAS support + gene set support)",
                  "Evidence range (Overall score)",
                  "GWAS support",
                  "Evidence range (GWAS support)",
                  "Gene set support",
                  "Evidence range (Gene set support)",
                  "Source"
                ],
                "column formatting": {
                  "Evidence range (Overall score)": {
                    "type": [
                      "value in class"
                    ]
                  },
                  "Evidence range (GWAS support)": {
                    "type": [
                      "value in class"
                    ]
                  },
                  "Evidence range (Gene set support)": {
                    "type": [
                      "value in class"
                    ]
                  }
                }
              }
            }
          }
        }
      },
      "filters": [
        {
          "field": "Association",
          "label": "Association",
          "type": "search",
          "label in bubble": "true"
        },
        {
          "field": "Program",
          "label": "Program",
          "type": "checkbox",
          "label in bubble": "true"
        }
      ]
    },
    {
      "section id": "phenotypes",
      "header": "CFDE phenotypes",
      "data point": {
        "type": "api",
        "url": "https://search.hugeamp.org/api/search/pgvector/phenotypes-with-factors?q=$userInput",
        "parameters": [
          "userInput"
        ],
        "parameters type": "replace",
        "data type": "json",
        "data wrapper": [
          "results"
        ]
      },
      "table format": {
        "data convert": [
          {
            "type": "raw",
            "field name": "Phenotype",
            "raw field": "phenotype_name"
          },
          {
            "type": "raw",
            "field name": "id",
            "raw field": "phenotype"
          },
          {
            "type": "raw",
            "field name": "Similarity score (1-0)",
            "raw field": "score"
          },
          {
            "type": "translate to categories",
            "field name": "Significance range",
            "raw field": "score",
            "categories": [
              {
                "name": "Highly Significant",
                "condition": "greater than",
                "range": 0.75
              },
              {
                "name": "Significant",
                "condition": "and",
                "range": [
                  0.5,
                  0.75
                ]
              },
              {
                "name": "Moderately Significant",
                "condition": "and",
                "range": [
                  0.25,
                  0.5
                ]
              },
              {
                "name": "Slightly Significant",
                "condition": "less than",
                "range": 0.25
              }
            ]
          },
          {
            "type": "raw",
            "field name": "Gene sets associated with phenotype",
            "raw field": "id"
          }
        ],
        "top rows": [
          "Phenotype",
          "Significance range",
          "Gene sets associated with phenotype"
        ],
        "column formatting": {
          "Gene sets associated with phenotype": {
            "type": [
              "dynamic subsection"
            ],
            "label": "Show",
            "subsection": {
              "data point": {
                "type": "bioindex",
                "url": "https://cfde-dev.hugeampkpnbi.org/api/bio/query/pigean-gene-set-phenotype?q=$phenotype,cfde&limit=10000",
                "continue url": "https://cfde-dev.hugeampkpnbi.org/api/bio/cont?limit=10000&token=",
                "parameters": [
                  "phenotype"
                ],
                "parameters type": "replace",
                "data type": "bioindex"
              },
              "table format": {
                "pre filters": [
                  {
                    "field": "Source",
                    "type": "filter out",
                    "values": [
                      "gene_set_list_msigdb_nohp",
                      "gene_set_list_mouse_2024"
                    ]
                  },
                  {
                    "field": "Model",
                    "type": "filter out",
                    "values": [
                      "mouse"
                    ]
                  }
                ],
                "data convert": [
                  {
                    "type": "raw",
                    "field name": "Gene set",
                    "raw field": "gene_set"
                  },
                  {
                    "type": "raw",
                    "field name": "Model",
                    "raw field": "gene_set_size"
                  },
                  {
                    "type": "raw",
                    "field name": "Joint effect",
                    "raw field": "beta",
                    "if no value": "0"
                  },
                  {
                    "type": "translate to categories",
                    "field name": "Evidence range (Joint effect)",
                    "raw field": "Joint effect",
                    "categories": [
                      {
                        "name": "Not Significant",
                        "condition": "less than",
                        "range": 0.01
                      },
                      {
                        "name": "Significant",
                        "condition": "and",
                        "range": [
                          0.01,
                          0.1
                        ]
                      },
                      {
                        "name": "Strongly Significant",
                        "condition": "and",
                        "range": [
                          0.1,
                          1
                        ]
                      },
                      {
                        "name": "Extremely Significant",
                        "condition": "greater than",
                        "range": 1
                      }
                    ]
                  },
                  {
                    "type": "raw",
                    "field name": "Marginal effect",
                    "raw field": "beta_uncorrected",
                    "if no value": "0"
                  },
                  {
                    "type": "translate to categories",
                    "field name": "Evidence range (Marginal effect)",
                    "raw field": "Marginal effect",
                    "categories": [
                      {
                        "name": "Not Significant",
                        "condition": "less than",
                        "range": 0.01
                      },
                      {
                        "name": "Significant",
                        "condition": "and",
                        "range": [
                          0.01,
                          0.1
                        ]
                      },
                      {
                        "name": "Strongly Significant",
                        "condition": "and",
                        "range": [
                          0.1,
                          1
                        ]
                      },
                      {
                        "name": "Extremely Significant",
                        "condition": "greater than",
                        "range": 1
                      }
                    ]
                  },
                  {
                    "type": "raw",
                    "field name": "Source",
                    "raw field": "source"
                  }
                ],
                "top rows": [
                  "Gene set",
                  "Joint effect",
                  "Evidence range (Joint effect)",
                  "Marginal effect",
                  "Evidence range (Marginal effect)",
                  "Source"
                ],
                "column formatting": {
                  "Evidence range (Joint effect)": {
                    "type": [
                      "value in class"
                    ]
                  },
                  "Evidence range (Marginal effect)": {
                    "type": [
                      "value in class"
                    ]
                  }
                }
              },
              "visualizer": {
                "label": "",
                "type": "scatter plot",
                "star key": null,
                "render type": "single plot",
                "group by": "Phenotype",
                "color by": "Source",
                "y axis field": "Joint effect",
                "y axis label": "Joint effect",
                "x axis field": "Marginal effect",
                "x axis label": "Marginal effect",
                "ticks decimal point": "4",
                "render by": "Gene set",
                "hover content": [
                  "Joint effect",
                  "Marginal effect",
                  "Source"
                ],
                "thresholds": {
                  "x": [
                    0.01
                  ],
                  "y": [
                    0.01
                  ],
                  "widtn": 2,
                  "dash": [
                    5,
                    5
                  ]
                },
                "height": 150,
                "width": 550,
                "plot margin": {
                  "left": 60,
                  "right": 20,
                  "top": 40,
                  "bottom": 50,
                  "bump": 5
                }
              }
            }
          }
        }
      },
      "filters": [
        {
          "field": "Significance range",
          "label": "Significance range",
          "type": "checkbox",
          "label in bubble": "true"
        }
      ]
    }
  ]
}

pageStyle:
.multi-section-card {
margin-top: 50px;
}

.research-narrative-options {
    /*margin-left: -100%  !important;*/
}

.text-align-center{
   text-align:center;
}
.fixed-header {
 position: relative !important;
}
.multi-section-card {
margin-bottom: 20px;
}
#rp_tabs_contents { 
/* background: none !important;
  border: none; */ }

#byor_single_search {
    border: 2px solid #ff6600;
    padding: 20px;
    width: 830px !important;
    margin-left: 0 !important;
}

.byor-single-search-results-wrapper {
    width: 830px !important;
margin-left: 0 !important;
}

span.Tclin > strong {
padding: 0 10px;
    border: solid 2px #337ab7;
    border-radius: 5px;
}
span.Tchem > strong {
padding: 0 10px;
    border: solid 2px #5bc0de;
    border-radius: 5px;
}
span.Tbio > strong {
padding: 0 10px;
    border: solid 2px #ffb259;
    border-radius: 5px;
}
span.Tdark > strong {
padding: 0 10px;
    border: solid 2px #d32f2f;
    border-radius: 5px;
}

.info-card-row {
    margin-bottom: 15px;
}

.info-card-row > .row-key {
    width: 150px; display: inline-block; vertical-align: top;
}

.info-card-row > .row-value {
    width: calc(100% - 150px);  display: inline-block;
}

#byor_single_search { border-color: #ff7f00; }

.volcano-plot-content {
text-align: center;
}


.multi-page-search-wrapper { /*display: none;*/}

.multi-page-search-wrapper.in-section-ui { display: block;}



/* alex css begin */

.single-search-wrapper {
  padding: 30px;
  display: flex;
  flex-direction: column;
  gap: 10px;
  align-items: flex-start;
}

.context-btns-wrapper {
  display: flex;
  gap: 10px;
}
.context-btns-wrapper .btn {
  text-wrap: nowrap;
  background: white;
  color: black;
  border: 1px solid #ccc;
}
.context-btns-wrapper .btn.active {
  background: #ff802c !important;
  border: 1px solid #ccc !important;
}
.context-btns-wrapper .btn.btn-warning {
  background: #ccc;
}
.context-btns-wrapper .btn.btn-warning:hover {
  background: #bbb;
}

.dataset-page-header {
  background: none;
  border: 0;
  display: none;
}

.kp-tabs-contents:has(.multi-page-search-wrapper) {
  /* background: none;
  border: none; */
}

.col-md-12:has(.multi-page-search-wrapper) {
  display: flex;
  flex-direction: column;
  gap: 20px;
}
.col-md-12{
  height: fit-content;
}

.tab-ui-wrapper {
  margin: 0;
  background: none;
  border-bottom: 0;
  padding: 0;
}
.tab-content-group {
  background: white;
  border-radius: 0 10px 10px 10px;
  border: 1px solid #ddd;
  padding: 10px 20px;
}
.tab-ui-wrapper .tab-ui-tab {
  border-bottom: 0;
}

button.show-hide-section, button.capture-data {
  display: none;
}

.tab-content-group:has(.multi-section) {
  padding: 10px 0;
}

.multi-section {
  background: white;
  padding: 10px 20px 30px 20px;
  border-radius: 10px;
  border-bottom: 0;
}

.multi-section .section-header {
  padding: 10px 5px;
}
.multi-section .section-header h4 {
  font-size: 22px;
}
.section-header h4 small {
  font-size: 22px !important;
  padding-left: 10px;
    border-left: solid 1px #dddddd;
    margin-left: 5px;
}

.table-total-rows {
  padding-top: 3px;
}
.table-ui-wrapper {
  display: flex;
  align-items: baseline;
  gap: 5px;
}
.tab-ui-wrapper .tab-ui-tab {
  border-bottom: 0;
  color: #5a5a5a;
  background: #ddd;
}
.tab-ui-wrapper .tab-ui-tab:hover {
  color: black;
}
.table-ui-wrapper .number-per-page {
  margin: 0;
  border-radius: 5px;
  border: solid 0.5px #aaa;
}
.convert-2-csv {
  margin: 0;
  border-radius: 5px;
  border: solid 0.5px #aaa;
}

/* tables */
.mbm-plot-content {
  margin: 0 0 20px 0;
}
.research-data-table-wrapper {
  margin: 0 15px;
}
table.research-data-table {
  border: 0 !important;
  text-align: left;
}
.research-data-table tbody:nth-child(odd) {
  background: #f9f9f9;
}

#section_IDG_gene .research-data-table td {
  border: 0 !important;
  padding: 10px 10px;
  vertical-align: top !important;
}

#section_IDG_gene .egl-table-page-ui-wrapper, #section_IDG_gene .table-total-rows, #section_IDG_gene .table-ui-wrapper {
  display: none;
}

#section_IDG_gene .table-wrapper { margin-top: 25px; }

th.Visit.Pharos { width: 120px !important; }

.research-data-table td {
  border: 0 !important;
  padding: 3px 10px;
  line-height: 1.5em;
}
.research-data-table > thead > tr > th {
  border: 0 !important;
  padding: 5px 10px;
}
.research-data-table > thead > tr > th.sortable-th {
  color: black;
}
[class*="cell-weight"] {
  padding-left: 10px;
}
.sortable-th:after {
  content: '';
  background: none;
  width: 10px;
  height: 10px;
  position: absolute;
  margin: 0 0 0 5px;
  bottom: 7px;
  border-right: 5px solid transparent;
  border-left: 5px solid transparent;
  border-top: 5px solid #b4b4b4;
  border-bottom: 5px solid transparent;
}
table.feature-table {
  border-bottom: 3px solid #cccccc;
}
.feature-table > tr > th.feature-title-th {
  background-color: #cccccc !important;
}
table.feature-table tr:nth-child(odd) {
  background: white;
}
table.feature-table th.feature-th-0 {
  background-color: #eeeeee !important;
  border-left: 0 !important;
  padding: 0.3rem 10px;
  border-bottom: 1px solid #ccc !important;
}

#section_general_gene_info_function .row-value.Function {
  font-size: 16px;
  line-height: 26px;
}

/* colors */  
table a {
  color: #ff6600 !important;
}
.show-evidence-btn {
  background: #ffa02c !important;
  border: 0;
}
.show-evidence-btn:hover {
  background: #dc5800 !important;
  color:white !important;
}
.tab-ui-wrapper .tab-ui-tab.loading > .flag {
  color: #ffaa2c;
}
.page-item.active .page-link {
  background-color: #ffa02c;
}
.page-link {
  color: #ff6600;
}

